# -*- coding: utf-8 -*-
# منزلة كل مصدر غير تراثي: (بيان المنزلة, درجة الدليل)
S = {
# ===== خبراء الطب =====
"A2-042": ("مستشفى آن وروبرت لوري للأطفال في شيكاغو هو مستشفى الأطفال الجامعي لكلية فاينبرغ للطب بجامعة نورثوسترن، ويعد من كبار مستشفيات الأطفال في الولايات المتحدة؛ والنص من إرشادات قسم العلاج الوظيفي فيه.", "إرشاد سريري لمستشفى أطفال جامعي"),
"A2-043": ("كان تشايلد مركز بحثي في جامعة ماكماستر الكندية، من المراكز العالمية المرجعية في بحوث نمو الطفل والإعاقة؛ ونموذج Partnering for Change من برامجه المعتمدة في مدارس أونتاريو.", "مادة مهنية لمركز بحثي جامعي"),
"A2-004": ("ابن سينا (ت 428 هـ) الشيخ الرئيس، وكتابه القانون في الطب ظل مرجع الطب في الشرق، ودرس في جامعات أوروبا بترجمته اللاتينية قرابة ستة قرون.", "مرجع طبي تراثي مؤسس"),
"A2-033": ("المعهد الوطني لصحة الطفل والتنمية البشرية أحد معاهد المعاهد الوطنية للصحة في الولايات المتحدة، أكبر جهة حكومية لتمويل البحث الطبي في العالم.", "مرجع رسمي لمعهد بحثي حكومي"),
"A2-036": ("البحث من قسم الوراثة الإكلينيكية بالمركز القومي للبحوث في القاهرة، أكبر مؤسسة بحثية حكومية في مصر؛ ونشر في مجلة طب الغدد الصماء والاستقلاب لدى الأطفال، وهي مجلة دولية محكمة.", "دراسة ميدانية على عينة مصرية"),
"A2-039": ("البحث من جامعة تشيلي، كبرى جامعات البلاد، ضمن دراسة أتراب النمو والسمنة؛ ومن مؤلفيه فيرونيكا ميريك من أعلام غدد الأطفال في أمريكا اللاتينية. والمجلة لسان الجمعية الأمريكية الشمالية لأمراض النساء لدى الأطفال والمراهقات.", "دراسة أتراب طولية"),
"A2-010": ("مارشيا هيرمان غيدنز من جامعة نورث كارولاينا، ودراستها على أكثر من سبعة عشر ألف فتاة في عيادات شبكة الأكاديمية الأمريكية لطب الأطفال غيرت فهم الأطباء لسن البلوغ. ومجلة طب الأطفال لسان الأكاديمية، من أرفع مجلات التخصص في العالم.", "دراسة سريرية واسعة متعددة المراكز"),
"A2-011": ("فرانك بيرو أستاذ طب المراهقين في مستشفى سينسيناتي للأطفال، والدراسة جزء من برنامج اتحادي أمريكي لبحوث البيئة والبلوغ. ومجلة طب الأطفال لسان الأكاديمية الأمريكية لطب الأطفال، من أرفع مجلات التخصص في العالم.", "دراسة أتراب طولية"),
"A2-012": ("دراسة كوبنهاغن للبلوغ من قسم النمو والتكاثر في مستشفى ريغسهوسبيتالت الجامعي، ومن مؤلفيها أندرس يول من أعلام غدد الأطفال في أوروبا. ومجلة طب الأطفال لسان الأكاديمية الأمريكية لطب الأطفال.", "دراسة مقارنة بين جيلين"),
"A2-013": ("تحليل بعدي لفريق مستشفى ريغسهوسبيتالت الجامعي في كوبنهاغن، جمع دراسات من قارات العالم. ومجلة جاما لطب الأطفال تصدرها الجمعية الطبية الأمريكية، وهي من أعلى مجلات التخصص أثرا.", "تحليل بعدي ومراجعة منهجية: أعلى درجات الدليل"),
"A2-014": ("كتاب نلسون في طب الأطفال المرجع الجامعي الأول في التخصص، يصدر عن دار إلزفير في طبعات متتابعة منذ منتصف القرن العشرين، ويدرس في كليات الطب عبر العالم.", "مرجع جامعي معتمد"),
"A2-022": ("جيمس تانر (1920–2010) من معهد صحة الطفل في لندن، واضع مراحل تانر للبلوغ التي يقيس بها أطباء العالم النضج إلى اليوم. ومجلة أمراض الطفولة تصدرها مجموعة المجلة الطبية البريطانية مع الكلية الملكية لطب الأطفال.", "دراسة طولية مؤسسة"),
"A2-025": ("لجنة خبراء في الغدد وطب الأطفال وعلم الأوبئة دعت إليها جهات أمريكية حكومية لمراجعة بيانات البلوغ من 1940 إلى 1994. ونشرت خلاصتها مجلة طب الأطفال لسان الأكاديمية الأمريكية لطب الأطفال.", "تقرير لجنة خبراء"),
"A2-016": ("منظمة الصحة العالمية الوكالة المتخصصة في الصحة العامة التابعة للأمم المتحدة، تأسست سنة 1948، ومقرها جنيف، وتعريفاتها العمرية معتمدة في وزارات الصحة عبر العالم.", "تعريف رسمي لهيئة أممية"),
"A2-032": ("مارشيا هيرمان غيدنز وفريقها في شبكة أبحاث العيادات التابعة للأكاديمية الأمريكية لطب الأطفال، على آلاف الفتيان من ولايات عدة. ونشرتها مجلة طب الأطفال لسان الأكاديمية.", "دراسة سريرية واسعة متعددة المراكز"),
"A2-034": ("ستات بيرلز مرجع طبي تعليمي محكم تستضيفه المكتبة الوطنية للطب في الولايات المتحدة ضمن رفوفها الإلكترونية، ويحدث دوريا.", "مرجع طبي محكم"),
"A2-035": ("دليل ميرك (MSD) من أقدم المراجع الطبية التي تصدر بلا انقطاع منذ سنة 1899؛ والمدخل لإيفان غرابر من مستشفى نيمورز للأطفال، بمراجعة أليشيا بيكارسكي من جامعة ولاية نيويورك الطبية.", "مرجع طبي مهني معتمد"),
"A2-037": ("الدراسة من جامعة تريانغولو مينيرو الاتحادية في البرازيل، ونشرتها مجلة أرشيف الغدد والاستقلاب، لسان الجمعية البرازيلية للغدد الصماء والاستقلاب.", "دراسة ميدانية على تلميذات"),
"A2-038": ("البحث من معهد عموم الهند للعلوم الطبية في نيودلهي، أرفع مؤسسة طبية في الهند؛ ونشرته المجلة الهندية للغدد والاستقلاب، لسان جمعية الغدد الصماء الهندية.", "دراسة ميدانية على فتيان"),
"A2-040": ("بحث على بيانات المسح الوطني الكوري للصحة والتغذية، شارك فيه طب الأطفال بجامعة إنجي وأندرس يول من كوبنهاغن؛ ونشرته مجلة العلوم الطبية الكورية، لسان الأكاديمية الكورية للعلوم الطبية.", "دراسة مسحية وطنية"),
"A2-041": ("البحث من معهد صحة الأطفال والمراهقين بجامعة بكين، على بيانات المسوح الوطنية الصينية لبنية الطلاب وصحتهم من 1995 إلى 2019. ومجلة أكتا بيدياتريكا مجلة طب أطفال سويدية النشأة تأسست سنة 1921.", "دراسة مسحية وطنية متكررة"),
"A2-046": ("مقياس الاستقلال الوظيفي للأطفال من وضع فريق جامعة ولاية نيويورك في بوفالو، ومنهم كارل غرينجر صاحب مقياس الاستقلال الوظيفي المعتمد في مراكز التأهيل عبر العالم. ونشرته مجلة طب الأطفال الإكلينيكي.", "دراسة معيارية لبناء مقياس"),
"A2-015": ("سوزان سوير من مستشفى الأطفال الملكي وجامعة ملبورن، رأست لجنة مجلة لانسيت لصحة المراهقين. والمجلة من سلسلة لانسيت، أعرق المجلات الطبية البريطانية وأوسعها أثرا، تأسست سنة 1823.", "رأي علمي محكم في مجلة كبرى"),
"A5-057": ("تقرير سريري رسمي للأكاديمية الأمريكية لطب الأطفال، أكبر هيئة لأطباء الأطفال في العالم، وتقاريرها مرجع الممارسة الطبية. ومايكل يوغمان من كلية الطب بجامعة هارفارد، وكريغ غارفيلد من جامعة نورثوسترن.", "بيان سريري لهيئة مهنية"),
"A5-058": ("آنا سركادي أستاذة طب الأطفال الاجتماعي في جامعة أوبسالا بالسويد، ومعها فرانك أوبركلايد من مركز صحة الطفل في ملبورن. ومجلة أكتا بيدياتريكا مجلة طب أطفال سويدية النشأة.", "مراجعة منهجية للدراسات الطولية: أعلى درجات الدليل"),
"A5-089": ("تقرير المكتب الإقليمي لأوروبا في منظمة الصحة العالمية، الذي يخدم ثلاثا وخمسين دولة، ومقره كوبنهاغن.", "تقرير رسمي لهيئة أممية"),
"A5-099": ("بيان الجمعية الكندية لطب الأطفال، الهيئة المهنية الوطنية لأطباء الأطفال في كندا؛ ومجلتها Paediatrics & Child Health لسانها الرسمي، وبياناتها مرجع الممارسة الطبية هناك.", "بيان سريري لهيئة مهنية"),
"A5-100": ("تقرير سريري رسمي للأكاديمية الأمريكية لطب الأطفال، أكبر هيئة لأطباء الأطفال في العالم، أعدته لجنتها المختصة بالجوانب النفسية والاجتماعية لصحة الطفل والأسرة.", "بيان سريري لهيئة مهنية"),
"A5-136": ("الأكاديمية الأمريكية للطب النفسي للأطفال والمراهقين الهيئة المهنية الجامعة لأطباء هذا التخصص في الولايات المتحدة، تأسست سنة 1953؛ وسلسلة حقائق للأسر نشرتها الرسمية للآباء.", "إرشاد رسمي لهيئة مهنية"),
"A5-137": ("الكلية الملكية للأطباء النفسيين الهيئة المهنية الرسمية للأطباء النفسيين في المملكة المتحدة، تمنح شهادة الاختصاص وتضع معايير الممارسة.", "إرشاد رسمي لهيئة مهنية"),
# ===== خبراء علم النفس =====
"A2-044": ("أديل دايموند من مؤسسي علم الأعصاب المعرفي النمائي، أستاذة في جامعة كولومبيا البريطانية وعضو الجمعية الملكية الكندية؛ ومجلة الإدراك من أرفع مجلات علم النفس المعرفي.", "دراسة تجريبية"),
"A2-045": ("أديل دايموند من مؤسسي علم الأعصاب المعرفي النمائي؛ ونشرت البحث مجلة علم النفس الحيوي النمائي، لسان الجمعية الدولية لعلم النفس الحيوي النمائي.", "دراسة تجريبية"),
"A2-006": ("أرنولد ساميروف من جامعة ميشيغان ومارشال هيث من جامعة دنفر، جمعا في الكتاب بحوث كبار علماء النمو؛ وصدر عن مطبعة جامعة شيكاغو ضمن سلسلة مؤسسة ماك آرثر في النمو.", "كتاب علمي جامع"),
"A2-007": ("شلدون وايت عالم نفس في جامعة هارفارد، وبحثه أصل القول بتحول الخامسة إلى السابعة في علم النمو، ونشر في سلسلة التقدم في نمو الطفل وسلوكه.", "بحث علمي مؤسس"),
"A2-008": ("جان بياجيه (1896–1980) عالم نفس سويسري في جامعة جنيف، مؤسس نظرية النمو المعرفي، وأكثر علماء النفس أثرا في فهم عقل الطفل.", "نظرية علمية مؤسسة"),
"A2-009": ("ليف فيجوتسكي (1896–1934) عالم نفس روسي، مؤسس النظرية الاجتماعية الثقافية في نمو الطفل، وما زالت مفاهيمه أساس التربية الحديثة.", "نظرية علمية مؤسسة"),
"A2-017": ("إريك إريكسون (1902–1994) أستاذ في جامعة هارفارد، صاحب نظرية مراحل النمو النفسي الاجتماعي، وكتابه الطفولة والمجتمع من أوسع كتب علم النفس انتشارا.", "نظرية علمية مؤسسة"),
"A2-026": ("بياجيه (1896–1980) مؤسس نظرية النمو المعرفي، وزميلته باربل إنهلدر من أبرز علماء النفس في جامعة جنيف؛ والكتاب أصل نظرية التفكير المجرد عند المراهق.", "نظرية علمية مؤسسة"),
"A2-031": ("لورنس شتاينبرغ أستاذ علم النفس في جامعة تمبل، من أبرز علماء المراهقة في العالم، ورأس جمعية بحوث المراهقة، واستندت المحكمة العليا الأمريكية إلى أبحاثه.", "كتاب علمي لعالم مرجع"),
"A5-112": ("تحليل بعدي لبيانات المشاركين الأفراد أجراه تعاون دولي في التعلق بالوالدين، من أعضائه ماريان باكرمانز كراننبرغ ومارينوس فان آيزندورن من هولندا، وهما من أكثر علماء التعلق أثرا في العالم.", "تحليل بعدي لبيانات الأفراد: أقوى أنواع التحليل البعدي"),
"A5-113": ("شيري ماديغان أستاذة في جامعة كالغاري، صاحبة كرسي بحث كندي في محددات نمو الطفل، ومعها كبار علماء التعلق من هولندا وبريطانيا. والنشرة النفسية أرفع مجلات جمعية علم النفس الأمريكية.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-114": ("مانويلا فيريسيمو من المعهد الجامعي لعلم النفس التطبيقي في لشبونة، ومعها براين فون من جامعة أوبرن من كبار باحثي التعلق؛ والمجلة تصدرها دار تايلور وفرانسيس.", "دراسة طولية"),
"A5-115": ("ناتاشا كابريرا من جامعة ماريلاند، وبريندا فولينغ من جامعة ميشيغان، وراشيل بار من جامعة جورجتاون؛ ومجلة آفاق في نمو الطفل تصدرها جمعية البحث في نمو الطفل، أعرق جمعيات التخصص.", "مراجعة علمية محكمة"),
"A5-116": ("ماريان باكرمانز كراننبرغ ومارينوس فان آيزندورن من أكثر علماء التعلق أثرا في العالم؛ ومجلة آفاق في نمو الطفل تصدرها جمعية البحث في نمو الطفل.", "مراجعة علمية محكمة"),
"A5-117": ("روث فيلدمان من جامعة بار إيلان، من أبرز الباحثين في الأساس العصبي والهرموني للرابطة بين الوالد وولده؛ ومجلة وقائع الأكاديمية الوطنية للعلوم من أرفع المجلات العلمية في العالم.", "دراسة تجريبية بالتصوير الوظيفي للدماغ"),
"A5-118": ("إيريني فلوري أستاذة في كلية لندن الجامعية، من أبرز باحثي الأبوة في بريطانيا؛ وكتابها صادر عن دار وايلي بلاكويل الأكاديمية.", "كتاب علمي محكم"),
"A5-059": ("رودولف شافر من رواد علم نفس النمو في بريطانيا، ودراسته من أشهر الدراسات في نظرية التعلق، وتصدر سلسلتها جمعية البحث في نمو الطفل، أعرق جمعيات التخصص.", "دراسة طولية مؤسسة"),
"A5-060": ("مايكل لامب أستاذ علم النفس في جامعة كامبريدج، ورأس قبلها قسم النمو الاجتماعي والانفعالي في المعهد الوطني الأمريكي لصحة الطفل؛ وكتابه هذا المرجع الجامع في الموضوع منذ طبعته الأولى سنة 1976.", "مرجع علمي جامع"),
"A5-061": ("مجلة نمو الطفل تصدرها جمعية البحث في نمو الطفل، وهي أرفع مجلات علم نفس النمو؛ ومن مؤلفي البحث مايكل لامب من جامعة كامبريدج وناتاشا كابريرا من جامعة ماريلاند.", "مراجعة علمية محكمة"),
"A5-062": ("جوان كيلي عالمة نفس إكلينيكية أمريكية، من رواد البحث في أحوال أبناء الطلاق منذ سبعينيات القرن العشرين؛ ومجلة العمليات الأسرية من أعرق مجلات العلاج الأسري، تأسست سنة 1962.", "مراجعة علمية محكمة"),
"A5-063": ("مايكل لامب من جامعة كامبريدج، وجوان كيلي من رواد بحوث الطلاق؛ ومجلة مراجعة محاكم الأسرة لسان رابطة محاكم الأسرة والمصالحة، يكتب فيها القضاة وعلماء النفس.", "مراجعة علمية محكمة"),
"A5-068": ("جوديث والرستين (1921–2012) صاحبة أطول دراسة طولية في أبناء الطلاق، تابعت فيها أسرا من كاليفورنيا خمسا وعشرين سنة؛ وجوان كيلي من رواد بحوث الطلاق.", "دراسة طولية مؤسسة"),
"A5-069": ("مايكل رتر (1933–2021) يعد أبا الطب النفسي للأطفال، من كلية كينغز في لندن، ونال لقب فارس لخدمته العلمية؛ وكتابه هذا راجع به نظرية الحرمان من الأم.", "مراجعة علمية مؤسسة"),
"A5-070": ("مايكل لامب أستاذ علم النفس في جامعة كامبريدج، أوسع الباحثين أثرا في علم نفس الأبوة؛ ومجلة نمو الطفل أرفع مجلات علم نفس النمو.", "دراسة ملاحظة طولية"),
"A5-071": ("ماري ماين من جامعة كاليفورنيا في بيركلي، من أعلام نظرية التعلق ومبتكرة مقابلة التعلق عند الراشدين؛ ومجلة نمو الطفل أرفع مجلات التخصص.", "دراسة ملاحظة تجريبية"),
"A5-072": ("كلاوس وكارين غروسمان من جامعة ريغنسبورغ الألمانية، أصحاب أطول الدراسات الطولية في التعلق في أوروبا؛ والمجلة تصدرها دار وايلي.", "دراسة طولية ست عشرة سنة"),
"A5-073": ("دانيال باكيت أستاذ في جامعة مونتريال، صاحب نظرية علاقة التنشيط بين الأب وولده؛ ومجلة النمو الإنساني تصدرها دار كارغر السويسرية.", "مراجعة نظرية محكمة"),
"A5-074": ("إيريني فلوري أستاذة في كلية لندن الجامعية، وآن بوكانان من جامعة أكسفورد؛ والدراسة على أتراب الدراسة الوطنية لنمو الطفل في بريطانيا، المولودين سنة 1958.", "دراسة أتراب وطنية طولية"),
"A5-075": ("رونالد رونر أستاذ في جامعة كونيتيكت، مؤسس نظرية القبول والرفض بين الأشخاص؛ ومجلة المراجعة العامة في علم النفس تصدرها جمعية علم النفس الأمريكية.", "مراجعة علمية محكمة"),
"A5-076": ("كايل برويت أستاذ إكلينيكي للطب النفسي للأطفال في مركز دراسة الطفل بجامعة ييل، من أرفع مراكز طب الأطفال النفسي في العالم.", "كتاب علمي لعالم مرجع"),
"A5-077": ("روس باركي أستاذ متميز في جامعة كاليفورنيا، من رواد البحث في الأبوة منذ سبعينيات القرن العشرين؛ والكتاب صادر عن مطبعة جامعة هارفارد.", "كتاب علمي لعالم مرجع"),
"A5-081": ("مايكل لامب أستاذ علم النفس في جامعة كامبريدج، أوسع الباحثين أثرا في علم نفس الأبوة؛ والمجلة تصدرها دار تايلور وفرانسيس.", "مراجعة علمية محكمة"),
"A5-082": ("هنري بيلر أستاذ علم النفس في جامعة رود آيلاند، من أوائل من درسوا أثر الأب في نمو الطفل.", "كتاب علمي"),
"A5-087": ("مايكل لامب أستاذ علم النفس في جامعة كامبريدج، أوسع الباحثين أثرا في علم نفس الأبوة؛ ومجلة حضانة الطفل مجلة محكمة متخصصة.", "مراجعة علمية محكمة"),
"A5-092": ("الدراسة من معهد كارولينسكا في ستوكهولم، الذي يمنح جائزة نوبل في الطب؛ والمجلة من أرفع مجلات الطب النفسي الوبائي، تصدرها دار سبرينغر.", "دراسة مسحية سكانية"),
"A5-095": ("الدراسة من جامعة أنتويرب البلجيكية على بيانات مشروع الطلاق في فلاندرز؛ ومجلة الشباب والمراهقة من أرفع مجلات التخصص، تصدرها دار سبرينغر.", "دراسة مسحية واسعة"),
# ===== خبراء علوم المجتمع والإنسان =====
"A2-027": ("باري بوغن عالم إنسان في جامعة لفبرة البريطانية، من أبرز الباحثين في تطور النمو البشري وأطوار حياة الإنسان؛ والكتاب السنوي لعلم الإنسان الطبيعي تصدره الجمعية الأمريكية لعلم الإنسان الطبيعي.", "مراجعة علمية محكمة"),
"A2-028": ("باري بوغن، ومعه هولي سميث من جامعة ميشيغان، من أعلام علم تطور النمو البشري؛ والمجلة الأمريكية لعلم الأحياء البشري لسان جمعية علم الأحياء البشري.", "مراجعة علمية محكمة"),
"A5-101": ("جمعية خدمات الأسرة والرفاه في هونغ كونغ من أقدم هيئات الخدمة الاجتماعية الأسرية هناك، تأسست سنة 1949.", "دراسة ميدانية لهيئة اجتماعية"),
"A5-125": ("رونالد رونر مؤسس نظرية القبول والرفض بين الأشخاص، ومعه عبد الخالق من جامعة كونيتيكت؛ ومجلة علم النفس عبر الثقافات لسان الرابطة الدولية لعلم النفس عبر الثقافات.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-126": ("مشروع الوالدية عبر الثقافات بقيادة جنيفر لانسفورد وكينيث دودج من جامعة ديوك، ومارك بورنشتاين من المعهد الوطني الأمريكي لصحة الطفل؛ ونشرته مجلة علم نفس الطفل والطب النفسي.", "دراسة طولية دولية"),
"A5-127": ("بحث على مسوح اليونيسف متعددة المؤشرات في 38 دولة، أجراه باحثون من جامعة هارفارد وجامعة آغا خان؛ ونشرته مجلة طب الأطفال لسان الأكاديمية الأمريكية لطب الأطفال.", "دراسة مسحية دولية"),
"A5-066": ("سارة بلافر هردي عالمة إنسان أمريكية، أستاذة فخرية في جامعة كاليفورنيا في ديفيس، وعضو الأكاديمية الوطنية للعلوم في الولايات المتحدة؛ وكتابها صادر عن مطبعة جامعة هارفارد.", "كتاب علمي لعالمة مرجع"),
"A5-094": ("الدراسة من مركز علم الاجتماع في جامعة لوفان الكاثوليكية، من أعرق جامعات أوروبا؛ ومجلة دراسات الأسرة تصدرها دار تايلور وفرانسيس.", "دراسة مسحية"),
"A5-096": ("سارة ألين وكيري دالي من جامعة غويلف الكندية، ضمن تحالف وطني للبحث في الأبوة مولته الهيئة الكندية لبحوث العلوم الاجتماعية والإنسانية.", "خلاصة بحثية جامعة"),
"A5-097": ("تقرير تشترك فيه منظمات من الولايات المتحدة وهولندا والمملكة المتحدة وجنوب إفريقيا، ومنها منظمة إنقاذ الطفولة.", "تقرير دولي"),
"A5-104": ("بول أماتو أستاذ علم الاجتماع في جامعة ولاية بنسلفانيا، من أوسع علماء الأسرة أثرا؛ والمجلة يصدرها مركز في جامعة برنستون مع مؤسسة بروكينغز.", "مراجعة علمية محكمة"),
"A5-067": ("باري هيولت أستاذ علم الإنسان في جامعة ولاية واشنطن، من رواد دراسة الأبوة في المجتمعات التقليدية؛ وكتابه صادر عن مطبعة جامعة ميشيغان.", "دراسة ميدانية إثنوغرافية"),
# ===== أضرار حرمان الطفل من أبيه =====
"A5-065": ("سارة ماكلاناهان (1940–2021) أستاذة علم الاجتماع في جامعة برنستون، مؤسسة دراسة الأسر الهشة ورفاه الطفل؛ والمراجعة السنوية لعلم الاجتماع من أرفع منشورات التخصص.", "مراجعة منهجية للأدلة السببية"),
"A5-105": ("الدراسة من المجلس الوطني للصحة والرعاية في السويد ومعهد كارولينسكا، على سجلات قرابة مليون طفل؛ ومجلة لانسيت أعرق المجلات الطبية البريطانية وأوسعها أثرا، تأسست سنة 1823.", "دراسة سجلات وطنية"),
"A5-106": ("سينثيا هاربر من جامعة كاليفورنيا، وسارة ماكلاناهان من جامعة برنستون؛ ومجلة بحوث المراهقة لسان جمعية بحوث المراهقة، والدراسة مدرجة في المكتبة الافتراضية لوزارة العدل الأمريكية.", "دراسة طولية وطنية"),
"A5-107": ("جينيفر هارمن أستاذة علم النفس في جامعة ولاية كولورادو، ومعها إدوارد كروك من جامعة كولومبيا البريطانية؛ والنشرة النفسية أرفع مجلات جمعية علم النفس الأمريكية.", "مراجعة علمية في مجلة كبرى"),
"A5-108": ("ويليام برنيت أستاذ فخري للطب النفسي في جامعة فاندربيلت؛ والمجلة تصدرها جمعية العلوم النفسية الأمريكية.", "مراجعة علمية محكمة"),
"A5-111": ("إدوارد كروك أستاذ الخدمة الاجتماعية في جامعة كولومبيا البريطانية بكندا، متخصص في سياسات الأسرة والطفل.", "مراجعة علمية محكمة"),
"A5-129": ("فريق من جامعة مانشستر وجامعة آرهوس الدنماركية، على السجلات الوطنية لأتراب المواليد الدنماركيين؛ والمجلة الأمريكية للطب الوقائي لسان الكلية الأمريكية للطب الوقائي.", "دراسة أتراب وطنية بالسجلات"),
"A5-130": ("الدراسة على أتراب مواليد شمال فنلندا 1966، من أشهر الأتراب الطبية في العالم، بسجلات وزارة العدل الفنلندية؛ والمجلة الدولية للطب النفسي الاجتماعي تصدرها دار سيج.", "دراسة أتراب ميلاد"),
"A5-131": ("تحليل بعدي لفريق من فيينا جمع أربعا وخمسين دراسة؛ ومجلة البحث النفسي مجلة طب نفسي محكمة تصدرها دار إلزفير.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-132": ("الدراسة من المعهد الوطني للصحة والرفاه في فنلندا، على أتراب المواليد الفنلنديين بالسجلات الوطنية؛ ومجلة علم الأوبئة وصحة المجتمع تصدرها مجموعة المجلة الطبية البريطانية.", "دراسة أتراب وطنية بالسجلات"),
"A5-133": ("دراسة تريلز الطولية من جامعة خرونينغن في هولندا، تتابع المشاركين من الطفولة إلى الرشد؛ والمجلة لسان الجمعية الأوروبية للطب النفسي للأطفال والمراهقين.", "دراسة طولية سكانية"),
"A5-109": ("إيمي بيكر عالمة نفس أمريكية، من أبرز الباحثين في تنفير الطفل من أحد والديه؛ والمجلة الأمريكية للعلاج الأسري مجلة محكمة تصدرها دار تايلور وفرانسيس.", "دراسة نوعية"),
"A5-110": ("بروس إليس أستاذ في جامعة يوتا، ومعه كينيث دودج من جامعة ديوك وديفيد فيرغسون من جامعة أوتاغو في نيوزيلندا؛ ومجلة نمو الطفل أرفع مجلات علم نفس النمو.", "دراسة طولية في بلدين"),
# ===== الدراسات العلمية في الرعاية المشتركة =====
"A5-019": ("الدراسة من مركز دراسات العدالة الصحية في جامعة ستوكهولم ومعهد كارولينسكا، على عينة وطنية من تلاميذ السويد؛ والمجلة من إصدارات مجموعة المجلة الطبية البريطانية.", "دراسة وطنية واسعة"),
"A5-020": ("الدراسة من فريق مركز دراسات العدالة الصحية في ستوكهولم ومعهد كارولينسكا وجامعة أوبسالا؛ ونشرتها مجلة أكتا بيدياتريكا لطب الأطفال.", "دراسة سكانية"),
"A5-021": ("ريتشارد ورشاك أستاذ إكلينيكي للطب النفسي في جامعة تكساس الجنوبية الغربية، وأيد تقريره مئة وعشرة من الباحثين والممارسين في العالم؛ والمجلة تصدرها جمعية علم النفس الأمريكية.", "تقرير إجماع علمي"),
"A5-023": ("مراجعة منهجية لباحثين من جامعة لافال في كيبيك، منهم سيلفي درابو من باحثات الأسرة بعد الانفصال في كندا.", "مراجعة منهجية: أعلى درجات الدليل"),
"A5-025": ("المعهد النرويجي للصحة العامة الهيئة الحكومية المختصة بالبحث في الصحة العامة، ويعد المراجعات المنهجية التي تعتمد عليها الوزارات.", "مراجعة منهجية حكومية"),
"A5-043": ("وليام فابريشيوس أستاذ علم النفس في جامعة ولاية أريزونا، من أبرز الباحثين في أحوال أبناء الطلاق؛ والمجلة تصدرها جمعية علم النفس الأمريكية.", "دراسة ميدانية"),
"A5-044": ("روبرت باوزرمان صاحب أشهر تحليلين بعديين في الحضانة المشتركة؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة تصدرها دار تايلور وفرانسيس.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-045": ("ليندا نيلسن أستاذة علم النفس التربوي في جامعة ويك فورست، وقد استمعت إلى شهادتها مجالس تشريعية أمريكية عدة؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة.", "خلاصة بحوث"),
"A5-090": ("الدراسة من جامعة وسط السويد على بيانات المسح الدولي لسلوك الأطفال الصحي في سن المدرسة؛ والمجلة الأوروبية للصحة العامة لسان الجمعية الأوروبية للصحة العامة.", "دراسة مسحية واسعة"),
"A5-091": ("الدراسة من وحدة علم الأوبئة الوطنية للولادة في جامعة أكسفورد، على دراسة أتراب الألفية، إحدى أكبر الدراسات الطولية الوطنية في بريطانيا.", "دراسة أتراب وطنية"),
"A5-102": ("ليندا نيلسن أستاذة علم النفس التربوي في جامعة ويك فورست؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة.", "خلاصة بحوث"),
"A5-119": ("إدوارد كروك أستاذ الخدمة الاجتماعية في جامعة كولومبيا البريطانية؛ والكتاب صادر عن مطبعة جامعتي مكغيل وكوينز، من كبرى دور النشر الجامعية في كندا.", "كتاب علمي محكم"),
"A5-120": ("سانفورد برافر من جامعة ولاية أريزونا، ومعه إيرا إلمان أستاذ القانون في الجامعة نفسها ومقرر مبادئ قانون انحلال الأسرة لدى معهد القانون الأمريكي؛ والمرجع صادر عن دار روتليدج.", "فصل في مرجع أكاديمي"),
"A5-121": ("باحثون من جامعتي بومبيو فابرا وكوينزلاند، ومعهم جنيفر باكستر من المعهد الأسترالي لدراسات الأسرة، على الدراسة الطولية الوطنية لأطفال أستراليا؛ ومجلة الزواج والأسرة لسان المجلس الوطني لعلاقات الأسرة.", "دراسة أتراب وطنية"),
"A5-122": ("هيلين نورمان من جامعة ليدز، وجيريمي ديفيز من معهد الأبوة؛ والمشروع ممول من مجلس البحوث الاقتصادية والاجتماعية البريطاني، ويربط أتراب الألفية بالسجلات التعليمية الرسمية.", "دراسة أتراب وطنية بالسجلات"),
"A5-123": ("دانيال ميلر من جامعة بوسطن، ومورين والر من جامعة كورنيل، ولينا نيبومنياشي من جامعة روتجرز، على العينة الوطنية الطولية للطفولة المبكرة؛ ومجلة الزواج والأسرة لسان المجلس الوطني لعلاقات الأسرة.", "دراسة طولية وطنية"),
"A5-124": ("الدراسة على بيانات دراسة الأسر الهشة ورفاه الطفل بجامعة برنستون؛ ومجلة مراجعة الخدمة الاجتماعية تصدرها مطبعة جامعة شيكاغو منذ سنة 1927.", "دراسة طولية وطنية"),
"A5-128": ("كاثرين بانتر بريك وجيمس ليكمان من جامعة ييل، ومعهما أدريان بيرجس من معهد الأبوة؛ ومجلة علم نفس الطفل والطب النفسي من أرفع مجلات التخصص.", "مراجعة منهجية: أعلى درجات الدليل"),
"A5-134": ("لورا فاولز ولاورا برناردي من جامعة لوزان، ومعهما باحثون من بولونيا وكوستاريكا؛ ومجلة بلوس ون مجلة علمية محكمة مفتوحة الإتاحة.", "مراجعة منهجية"),
"A5-135": ("الدراسة من مركز نورس البحثي وجامعة بيرغن، على المسح السكاني لشباب هوردالاند؛ والمجلة الإسكندنافية للصحة العامة مجلة محكمة لدول الشمال الأوروبي.", "دراسة سكانية مقطعية"),
"A5-022": ("روبرت باوزرمان جمع في تحليله ثلاثا وثلاثين دراسة؛ ومجلة علم نفس الأسرة تصدرها جمعية علم النفس الأمريكية.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-024": ("ليندا نيلسن أستاذة في جامعة ويك فورست، من أكثر الباحثين كتابة في الرعاية المشتركة؛ ومجلة حضانة الطفل مجلة محكمة يكتب فيها القضاة وعلماء النفس والباحثون.", "خلاصة بحوث"),
"A5-026": ("جوان كيلي ومايكل لامب من كبار باحثي الطلاق والأبوة؛ ومجلة مراجعة محاكم الأسرة لسان رابطة محاكم الأسرة والمصالحة.", "مراجعة علمية محكمة"),
"A5-046": ("وليام فابريشيوس ولين لوكن من جامعة ولاية أريزونا؛ ومجلة علم نفس الأسرة تصدرها جمعية علم النفس الأمريكية.", "دراسة ميدانية"),
"A5-047": ("ثورولفور بيارناسون من جامعة أكوريري في آيسلندا، على المسح الدولي لسلوك الأطفال الصحي في سن المدرسة بإشراف منظمة الصحة العالمية؛ ومجلة دراسات الأسرة المقارنة مجلة محكمة.", "دراسة دولية مقارنة"),
"A5-048": ("سانفورد برافر أستاذ علم النفس في جامعة ولاية أريزونا، من رواد البحث في آثار الطلاق على الآباء والأبناء؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة.", "مراجعة تحليلية"),
"A5-049": ("بول أماتو من جامعة ولاية بنسلفانيا، من أوسع علماء الأسرة أثرا، جمع في تحليله ثلاثا وستين دراسة؛ ومجلة الزواج والأسرة لسان المجلس الوطني لعلاقات الأسرة.", "تحليل بعدي: أعلى درجات الدليل"),
"A5-050": ("آنيا شتاينباخ أستاذة علم الاجتماع في جامعة دويسبورغ إيسن بألمانيا؛ ومجلة العمليات الأسرية من أعرق مجلات العلاج الأسري.", "مراجعة علمية محكمة"),
"A5-051": ("خلاصة ندوة خبراء رابطة محاكم الأسرة والمصالحة، الرابطة الدولية للقضاة والمحامين وعلماء النفس في قضايا الأسرة؛ أعدتها مارشا كلاين برويت ومعها هربي ديفونزو أستاذ القانون في جامعة هوفسترا.", "خلاصة إجماع مهني"),
"A5-056": ("يان تورونن باحث في وحدة الديموغرافيا بجامعة ستوكهولم؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة.", "دراسة سكانية"),
"A5-064": ("ليندا نيلسن أستاذة في جامعة ويك فورست؛ والمجلة تصدرها جمعية علم النفس الأمريكية، تعنى بصلة علم النفس بالقانون والسياسات العامة.", "مراجعة علمية محكمة"),
"A5-078": ("وليام فابريشيوس أستاذ علم النفس في جامعة ولاية أريزونا؛ ومجلة العلاقات الأسرية يصدرها المجلس الوطني لعلاقات الأسرة في الولايات المتحدة.", "دراسة ميدانية"),
"A5-079": ("إدوارد كروك أستاذ الخدمة الاجتماعية في جامعة كولومبيا البريطانية بكندا، متخصص في سياسات الأسرة والطفل؛ والمجلة الأمريكية للعلاج الأسري مجلة محكمة.", "مراجعة علمية محكمة"),
"A5-080": ("إد سبرويت باحث في علم الاجتماع بجامعة أوترخت الهولندية، من أعرق الجامعات الأوروبية؛ ومجلة الطلاق والزواج الثاني مجلة محكمة متخصصة.", "دراسة مسحية"),
"A5-083": ("ريتشارد ورشاك أستاذ إكلينيكي للطب النفسي في جامعة تكساس الجنوبية الغربية، صاحب تقرير الإجماع الذي أيده مئة وعشرة من الباحثين.", "مراجعة علمية محكمة"),
"A5-084": ("لاورا برناردي أستاذة في جامعة لوزان، وديميتري مورتلمانز أستاذ في جامعة أنتويرب؛ والكتاب صادر عن دار سبرينغر مفتوح الإتاحة، بفصول لباحثين من دول عدة.", "كتاب علمي جماعي محكم"),
"A5-085": ("إيما فرانسون وأندرس هيرن ومالين بيرغستروم من مركز دراسات العدالة الصحية في جامعة ستوكهولم ومعهد كارولينسكا، أصحاب أوسع بحوث الإقامة المشتركة في السويد.", "مراجعة علمية محكمة"),
"A5-086": ("لارا أوغستين باحثة في جامعة دويسبورغ إيسن الألمانية؛ ومجلة بحوث الأسرة مجلة ألمانية محكمة متخصصة.", "دراسة طولية"),
"A5-088": ("سانفورد برافر من جامعة ولاية أريزونا، ومايكل لامب من جامعة كامبريدج، جمعا آراء اثني عشر خبيرا من كبار الباحثين.", "خلاصة آراء الخبراء"),
"A5-093": ("دان أولويوس (1931–2020) من جامعة برغن، رائد البحث العالمي في التنمر بين التلاميذ؛ ومعه كيرستي بريفيك.", "دراسة مسحية"),
# ===== المواثيق والهيئات الدولية =====
"A5-003": ("لجنة حقوق الطفل هيئة من ثمانية عشر خبيرا مستقلا تراقب تنفيذ اتفاقية حقوق الطفل، وتعليقاتها العامة التفسير المعتمد لنصوص الاتفاقية.", "تفسير رسمي لهيئة أممية"),
"A5-004": ("الجمعية البرلمانية لمجلس أوروبا، تضم نوابا من برلمانات ست وأربعين دولة أوروبية.", "قرار برلماني دولي"),
"A5-027": ("وثيقة عالم صالح للأطفال اعتمدتها الجمعية العامة للأمم المتحدة في دورتها الاستثنائية الخاصة بالطفل سنة 2002، بحضور رؤساء الدول والحكومات.", "وثيقة أممية"),
"A5-028": ("الجمعية البرلمانية لمجلس أوروبا، تضم نوابا من برلمانات ست وأربعين دولة أوروبية.", "قرار برلماني دولي"),
"A5-030": ("لجنة الشؤون الاجتماعية والصحة في الجمعية البرلمانية لمجلس أوروبا، ورأيها جزء من الوثائق الرسمية للقرار 2079.", "رأي لجنة برلمانية دولية"),
"A5-001": ("أوسع معاهدات حقوق الإنسان تصديقا في العالم، اعتمدتها الجمعية العامة للأمم المتحدة سنة 1989، وصدقت عليها مصر سنة 1990.", "معاهدة دولية ملزمة"),
"A5-002": ("أوسع معاهدات حقوق الإنسان تصديقا في العالم، اعتمدتها الجمعية العامة للأمم المتحدة سنة 1989، وصدقت عليها مصر سنة 1990.", "معاهدة دولية ملزمة"),
"A5-005": ("معاهدة إفريقية لحقوق الطفل، اعتمدتها منظمة الوحدة الإفريقية سنة 1990، ونفذت سنة 1999.", "معاهدة إقليمية ملزمة"),
"A5-029": ("الجمعية البرلمانية لمجلس أوروبا، تضم نوابا من برلمانات ست وأربعين دولة أوروبية.", "قرار برلماني دولي"),
# ===== التشريعات المقارنة =====
"A5-006": ("قانون الوالدين والأولاد السويدي هو التشريع الجامع لأحكام الطفل والوالدين في السويد؛ والسويد من أعلى دول العالم في نسبة الإقامة المتناوبة بعد الفرقة.", "تشريع نافذ"),
"A5-007": ("قانون 18 يوليو 2006 البلجيكي أدخل في القانون المدني تقديم الإقامة المتساوية عند طلب أحد الوالدين، وكان من أوائل القوانين الأوروبية في ذلك.", "تشريع نافذ"),
"A5-015": ("كنتاكي أول ولاية أمريكية جعلت الحضانة المشتركة والوقت المتساوي أصلا مفترضا في كل قضايا الحضانة، بقانون أقره مجلسا الولاية بأغلبية ساحقة.", "تشريع نافذ"),
"A5-016": ("شهادة مقدمة إلى لجنة تشريعية في ولاية كانساس، محفوظة في السجل الرسمي للهيئة التشريعية للولاية.", "وثيقة تشريعية رسمية"),
"A5-034": ("قانون الطلاق الكندي قانون اتحادي يسري في كل المقاطعات، وتعديله سنة 2021 أول تعديل جوهري لأحكام الرعاية منذ أكثر من عشرين عاما.", "تشريع اتحادي نافذ"),
"A5-035": ("شرح رسمي صادر عن وزارة العدل الكندية لتعليل نصوص قانون الطلاق المعدل.", "شرح حكومي رسمي"),
"A5-053": ("قانون الأطفال والأسر البريطاني لسنة 2014 عدل قانون الأطفال لسنة 1989، التشريع الجامع لأحكام الطفل في إنجلترا وويلز.", "تشريع نافذ"),
"A5-054": ("قانون ولاية أريزونا المعدل سنة 2012، وتطبقه محاكم الأسرة في الولاية.", "تشريع نافذ"),
"A5-055": ("قانون ولاية أريزونا في الحضانة، وتطبقه محاكم الأسرة في الولاية.", "تشريع نافذ"),
"A5-098": ("لجنة القانون في الهند هيئة حكومية دائمة تقترح إصلاح التشريعات، وقدم تقريرها هذا رئيسها القاضي أجيت براكاش شاه إلى وزير القانون والعدل.", "تقرير هيئة حكومية تشريعية"),
"A5-008": ("القانون المدني الفرنسي أصل القوانين المدنية في أوروبا والعالم العربي، وأدخل الإقامة المتناوبة بقانون 4 مارس 2002.", "تشريع نافذ"),
"A5-009": ("القانون المدني الإيطالي، ونص الحضانة المشتركة فيه مقرر بقانون سنة 2006.", "تشريع نافذ"),
"A5-010": ("القانون المدني الألماني من أشهر التقنينات المدنية في العالم، نافذ منذ سنة 1900.", "تشريع نافذ"),
"A5-011": ("القانون المدني الألماني من أشهر التقنينات المدنية في العالم، نافذ منذ سنة 1900.", "تشريع نافذ"),
"A5-013": ("قانون اتحادي برازيلي صدر سنة 2014، جعل الحضانة المشتركة القاعدة في البلاد كلها.", "تشريع اتحادي نافذ"),
"A5-014": ("القانون المدني والتجاري الأرجنتيني الموحد، نافذ منذ سنة 2015.", "تشريع نافذ"),
"A5-017": ("تعديل القانون المدني الياباني أقره البرلمان سنة 2024، وهو أول تغيير لأحكام الولاية بعد الطلاق منذ نحو ثمانية عقود.", "تشريع نافذ"),
"A5-018": ("قانون صادر في إمارة أبوظبي سنة 2021 لتنظيم الأحوال الشخصية المدنية، تطبقه محكمة أبوظبي للأسرة.", "تشريع نافذ"),
"A5-036": ("القانون المدني الهولندي، ونص التوزيع المتكافئ للرعاية فيه مقرر بقانون تعزيز استمرار الوالدية سنة 2009.", "تشريع نافذ"),
"A5-037": ("القانون المدني السويسري من أدق التقنينات المدنية الأوروبية، ونص النظر في الحضانة المتناوبة فيه نافذ منذ سنة 2017.", "تشريع نافذ"),
"A5-038": ("القانون المدني الإسباني، ويفسره قضاء المحكمة العليا الإسبانية التي جعلت الحضانة المشتركة هي الأصل.", "تشريع نافذ"),
"A5-039": ("قانون برتغالي صدر سنة 2020، أجاز للمحكمة تقرير الإقامة المتناوبة مراعاة لمصلحة الطفل.", "تشريع نافذ"),
"A5-040": ("قانون ولاية أركنساس لسنة 2021، جعل الحضانة المشتركة أصلا لا ينقض إلا بدليل واضح مقنع.", "تشريع نافذ"),
"A5-103": ("قانون اتحادي برازيلي خاص بمكافحة تنفير الطفل من أحد والديه، من أوائل القوانين في العالم في هذا الباب.", "تشريع اتحادي نافذ"),
# ===== القضاء =====
"A5-012": ("أعلى هيئة قضائية في إسبانيا في غير المسائل الدستورية، وأحكامها تنشئ الاجتهاد الذي تتبعه المحاكم.", "حكم قضائي ملزم"),
"A5-031": ("محكمة دولية في ستراسبورغ أنشأها مجلس أوروبا سنة 1959، تفصل في انتهاكات الاتفاقية الأوروبية لحقوق الإنسان، وأحكامها ملزمة لست وأربعين دولة.", "قضاء دولي مستقر"),
"A5-032": ("محكمة دولية في ستراسبورغ أنشأها مجلس أوروبا سنة 1959، وأحكامها ملزمة لست وأربعين دولة.", "حكم قضائي دولي ملزم"),
"A5-033": ("محكمة دولية في ستراسبورغ أنشأها مجلس أوروبا سنة 1959، وأحكامها ملزمة لست وأربعين دولة.", "قضاء دولي مستقر"),
"A5-052": ("المحكمة العليا للاستئناف في ولاية فرجينيا الغربية أعلى محاكم الولاية، وتتولى تدريب قضاتها؛ والمادة منشورة على موقعها الرسمي.", "مادة تدريب قضائي رسمية"),
# ===== مصر =====
"A1-049": ("محمد زيد الأبياني مدرس الشريعة الإسلامية بمدرسة الحقوق الخديوية في القاهرة، وشرحه على تقنين قدري باشا من أعمدة فقه الأحوال الشخصية في مصر.", "شرح فقهي معتمد"),
"A1-030": ("محمد قدري باشا (1821–1888) وزير الحقانية في مصر، قنن فقه الأحوال الشخصية على مذهب أبي حنيفة في مواد، فصار كتابه مرجع المحاكم الشرعية المصرية.", "تقنين فقهي معتمد"),
"A1-031": ("الشيخ محمد أبو زهرة (1898–1974) أستاذ الشريعة في جامعة القاهرة وعضو مجمع البحوث الإسلامية، من أكبر فقهاء مصر في القرن العشرين.", "مرجع فقهي معتمد"),
"A1-028": ("قانون الطفل المصري هو التشريع الجامع لحقوق الطفل في مصر، صدر سنة 1996 وعدل تعديلا واسعا سنة 2008.", "تشريع مصري نافذ"),
"A1-029": ("قانون الطفل المصري هو التشريع الجامع لحقوق الطفل في مصر، وبهذه المادة صارت اتفاقية حقوق الطفل حدا أدنى ملزما في القانون المصري نفسه.", "تشريع مصري نافذ"),
}
